#!/usr/bin/env python3
"""fix_pixel_bosses2.py -- The other six Literary Scrimmage bosses as animated pixel sprites, and the boss's
name on the plate (needs fix_pixel_bosses.py).

Run from the repo root:   python3 fix_pixel_bosses2.py
Undo:                     restore src/game.src.html from the .bak this writes.

WHAT IT ADDS (pixel mode only -- the Tune switch / Reduce motion keep the classic boss cards)
  * Dyefone, Sandroid, Hexbox, Pintendo, SicSoc and Sinsta-Ram join Claystation and the Over-lord:
    standing on the page outside the card, idle / hurt / block / attack / taunt motion, a red recolour
    when enraged, pixel dissolve on defeat. Colour accents survive pixelation (SicSoc's neon hair,
    Sinsta-Ram's gold horns).
  * Each has its own animated layer: Dyefone ink drips + notification pops, Sandroid sand trickle +
    pixel blocks, Hexbox a pulsing red ring + error pops, Pintendo coin pops + flying needles, SicSoc
    neon flicker + music notes, Sinsta-Ram a camera flash + likes.
  * The plate under every pixel boss shows the boss's name (instead of "ALGORITHM CORE"), shrunk to fit.
  * Wide bosses (Claystation, Pintendo, SicSoc) may be up to 1.35x the card's width, never over the Lens
    slot or the moves panel.

HOW IT HOOKS IN (additive block + 3 edited lines + 1 inserted line, all inside fix_pixel_bosses code)
  * abcPxBossId: any boss whose sprite exists is recognised (was Claystation / Over-lord only).
  * abcPxBossPose: a pose without its own layer list uses the idle one.
  * abcPxBossPlace: wide-boss width rule (by the idle sprite's proportions).
  * abcPxBossSync: abcPxBossName() just before placing the boss.
"""
import os, sys, shutil, datetime
SRC = os.path.join('src', 'game.src.html')
MARK = '/* fix_pixel_bosses2 */'
TAG = '[fix_pixel_bosses2]'
if not os.path.exists(SRC):
    sys.exit(f'{TAG} ERROR: run from the repo root (src/game.src.html not found).')
s = open(SRC, encoding='utf-8').read()
if MARK in s:
    sys.exit(f'{TAG} Already applied -- nothing to do.')
if '/* fix_pixel_bosses */' not in s:
    sys.exit(f'{TAG} ERROR: run fix_pixel_bosses.py first.')
H = '   /* fix_pixel_bosses2 */'
EDITS = [
  ('end of fix_pixel_bosses block', "dead:PXB.dead}; }}});\n}\n", None),
  ('abcPxBossId mapping', "    if(c._overlord) return 'over'; if(c.id==='boss_claystation') return 'clay'; }catch(e){}",
     "    if(c._overlord) return 'over'; if(c.id==='boss_claystation') return 'clay'; { const k=String(c.id||'').replace(/^boss_/,''); if(PXB_ART[k]) return k; } }catch(e){}"+H),
  ('rig fallback', "  PXB.rig.set((RIGS[boss]||{})[st]||[],a.w,a.h,s);",
     "  PXB.rig.set((RIGS[boss]||{})[st]||(RIGS[boss]||{}).idle||[],a.w,a.h,s);"+H),
  ('wide-boss width', "  const cx=c.left+c.width/2; let wcap=c.width*(PXB.boss==='clay'?1.35:1.15);",
     "  const cx=c.left+c.width/2, _ia=PXB_ART[PXB.boss].idle; let wcap=c.width*(_ia.w/_ia.h>1.15?1.35:1.15);"+H),
  ('sync place', "  abcPxBossPlace();\n  if(!PXB.st) abcPxBossPose(abcPxBossBase());",
     "  try{ abcPxBossName(); }catch(e){}"+H+"   /* before placing: the name can change the plate's height */\n  abcPxBossPlace();\n  if(!PXB.st) abcPxBossPose(abcPxBossBase());"),
]
for l, a, _ in EDITS:
    n = s.count(a)
    if n != 1:
        sys.exit(f'{TAG} ERROR: anchor "{l}" found {n} times (expected 1). Nothing written.')

JS = r'''/* fix_pixel_bosses2 */ /* ---- the other six Mal-gorithms as pixel bosses + the boss name on the plate ----
   Dyefone, Sandroid, Hexbox, Pintendo, SicSoc, Sinsta-Ram: one drawing each (pixelated, colour accents kept
   for SicSoc's neon and Sinsta-Ram's horns), a red recolour when enraged, and their own animated layer. */
Object.assign(PXB_ART,{"dyefone":{"idle":{"url":"data:image/png;base64,","w":101,"h":102},"rage":{"url":"data:image/png;base64,","w":101,"h":102}},"sandroid":{"idle":{"url":"data:image/png;base64,","w":116,"h":102},"rage":{"url":"data:image/png;base64,","w":116,"h":102}},"hexbox":{"idle":{"url":"data:image/png;base64,","w":106,"h":102},"rage":{"url":"data:image/png;base64,","w":106,"h":102}},"pintendo":{"idle":{"url":"data:image/png;base64,","w":132,"h":98},"rage":{"url":"data:image/png;base64,","w":132,"h":98}},"sicsoc":{"idle":{"url":"data:image/png;base64,","w":128,"h":106},"rage":{"url":"data:image/png;base64,","w":128,"h":106}},"sinstaram":{"idle":{"url":"data:image/png;base64,","w":99,"h":102},"rage":{"url":"data:image/png;base64,","w":99,"h":102}}});
Object.assign(RIG_ICONS,{mail:["#####","##.##","#.#.#","#...#","#####"],bang:[".#.",".#.",".#.","...",".#."],coin:[".###.","#.#.#","#.##.","#.#.#",".###."],note:["..##","..#.","..#.","###.","##.."],blk:["##..","##..","####","####"]});
Object.assign(RIG_ICOL,{mail:'#f6eedb',bang:'#ff6a3d',coin:'#ffd45e',note:'#ff7ae0',blk:'#cfc4ae'});
Object.assign(RIG_LAYERS,{
  /* ink drops fall from splats */
  drip:function(x,L,t){ L.from.forEach(function(p,i){ const life=(t+i*5)%14, len=L.len||16; if(life>=10) return; const y=p[1]+Math.min(len,life*2);
      x.fillStyle=L.col||RIGC.ink; x.fillRect(p[0],p[1],1,Math.max(1,y-p[1]-2)); x.fillRect(p[0]-1,y-1,3,3); if(life>=8){ x.fillRect(p[0]-3,p[1]+len+1,7,1); } }); },
  /* sand / grit trickling down */
  sand:function(x,L,t){ L.from.forEach(function(p,i){ for(let k=0;k<4;k++){ const life=(t+k*3+i*2)%10, yy=p[1]+life*2, xx=p[0]+((k*7+i)%3)-1;
      x.fillStyle=k%2?'#cfc4ae':'#9c9080'; x.fillRect(xx,yy,1,1); } }); },
  /* the red ring: segments light up around a circle */
  redring:function(x,L,t){ const c=L.at, r=L.r; for(let a=0;a<4;a++){ const on=(t>>1)%4===a || t%8<2; if(!on) continue;
      for(let q=0;q<1.57;q+=.06){ const ang=a*1.5708+q; x.fillStyle=t%8<2?'#ff6a3d':'#a8321e'; x.fillRect(Math.round(c[0]+Math.cos(ang)*r),Math.round(c[1]+Math.sin(ang)*r),1,1); x.fillRect(Math.round(c[0]+Math.cos(ang)*(r+1)),Math.round(c[1]+Math.sin(ang)*(r+1)),1,1); } } },
  /* needles shoot out sideways */
  needle:function(x,L,t){ const p=L.from, dir=L.dir||1; for(let k=0;k<3;k++){ const life=(t+k*3)%9; if(life>6) continue; const xx=p[0]+dir*life*5, yy=p[1]+(k-1)*6;
      x.fillStyle=RIGC.ink; x.fillRect(xx-(dir>0?6:0),yy,6,1); x.fillStyle=RIGC.white; x.fillRect(xx+(dir>0?0:-1),yy,1,1); } },
  /* camera flash at a lens */
  flash:function(x,L,t){ const ph=t%(L.every||22); if(ph>3) return; const c=L.at, n=[2,6,9,5][ph];
      x.fillStyle=ph<3?RIGC.white:'rgba(255,251,232,.6)'; for(let i=-n;i<=n;i++){ x.fillRect(c[0]+i,c[1],1,1); x.fillRect(c[0],c[1]+i,1,1); } for(let i=-Math.floor(n*.6);i<=Math.floor(n*.6);i++){ x.fillRect(c[0]+i,c[1]+i,1,1); x.fillRect(c[0]+i,c[1]-i,1,1); }
      if(ph<2){ x.fillStyle='rgba(255,251,232,.45)'; x.fillRect(c[0]-3,c[1]-3,7,7); } },
  /* neon flicker: random accent pixels inside a box */
  flick:function(x,L,t){ const b=L.box, r=rigRng(t*17+5); for(let i=0;i<(L.n||10);i++){ x.fillStyle=L.cols[Math.floor(r()*L.cols.length)]; x.fillRect(b[0]+Math.floor(r()*b[2]),b[1]+Math.floor(r()*b[3]),1,1); } }
});
Object.assign(RIGS,{
dyefone:{
    idle:[{t:'blink',eyes:[[43,24,5,10],[55,24,5,10]],lid:'#cfc4ae',line:'#1b1410'},{t:'scan',box:[30,14,32,60],noise:3},{t:'drip',from:[[86,24],[12,66],[90,18]]},{t:'ping',from:[[84,6],[14,50],[80,60],[28,74]],icons:['mail','bang','bell','mail'],every:3}],
    hurt:[{t:'scan',box:[30,14,32,60],noise:40},{t:'drip',from:[[86,24],[12,66]]}],
    taunt:[{t:'scan',box:[30,14,32,60]},{t:'ping',from:[[84,6],[14,50],[80,60],[46,0]],icons:['bang','mail','bell'],every:2}],
    rage:[{t:'steam',from:[[46,10],[60,8]],col:'#f08a52'},{t:'drip',from:[[86,24],[12,66],[90,18],[20,60]]},{t:'ping',from:[[84,6],[14,50],[46,0]],icons:['err','bang','err'],every:2}],
    defeat:[{t:'steam',from:[[46,30]]}] },
  sandroid:{
    idle:[{t:'blink',eyes:[[53,15,4,5],[66,15,4,5]],lid:'#cfc4ae',line:'#1b1410'},{t:'sand',from:[[30,66],[88,70],[44,96],[76,96],[20,48]]},{t:'ping',from:[[86,18],[96,30],[22,30]],icons:['blk','blk','load'],every:4}],
    hurt:[{t:'sand',from:[[30,66],[88,70],[44,96],[76,96],[60,40],[50,60]]},{t:'scan',box:[48,8,26,22],noise:20}],
    taunt:[{t:'sand',from:[[30,66],[88,70]]},{t:'ping',from:[[86,18],[60,0],[22,30]],icons:['blk','load','blk'],every:3}],
    rage:[{t:'steam',from:[[56,4],[70,6]],col:'#f08a52'},{t:'sand',from:[[30,66],[88,70],[44,96],[76,96],[60,50]]},{t:'ping',from:[[86,18],[60,0]],icons:['err','blk'],every:2}],
    defeat:[{t:'sand',from:[[40,40],[60,30],[80,40],[50,60],[70,60]]}] },
  hexbox:{
    idle:[{t:'scan',box:[33,12,30,28]},{t:'blink',eyes:[[42,19,4,7],[52,19,4,7]],lid:'#1b1410',line:'#9c9080'},{t:'redring',at:[47,57],r:12},{t:'spark',at:[[14,72],[96,72]],every:5},{t:'ping',from:[[48,2],[70,6],[30,6]],icons:['err','load','err'],every:4}],
    hurt:[{t:'scan',box:[33,12,30,28],noise:40},{t:'redring',at:[47,57],r:12}],
    taunt:[{t:'scan',box:[33,12,30,28]},{t:'redring',at:[47,57],r:12},{t:'ping',from:[[48,2],[70,6],[30,6]],icons:['err','pad','err'],every:2}],
    rage:[{t:'scan',box:[33,12,30,28],noise:14},{t:'redring',at:[47,57],r:12},{t:'redring',at:[47,57],r:15},{t:'steam',from:[[48,6]],col:'#f08a52'},{t:'spark',at:[[14,72],[96,72],[47,57]],every:2}],
    defeat:[{t:'steam',from:[[48,20],[60,30]]},{t:'redring',at:[47,57],r:12}] },
  pintendo:{
    idle:[{t:'scan',box:[36,20,50,38],noise:3},{t:'needle',from:[98,54],dir:1},{t:'ping',from:[[60,10],[86,14],[40,14],[110,4]],icons:['coin','coin','pad','coin'],every:3}],
    hurt:[{t:'scan',box:[36,20,50,38],noise:40},{t:'ping',from:[[60,10],[86,14]],icons:['coin'],every:2}],
    taunt:[{t:'scan',box:[36,20,50,38]},{t:'ping',from:[[60,10],[86,14],[40,14],[110,4]],icons:['coin','coin','coin'],every:2},{t:'needle',from:[98,54],dir:1}],
    rage:[{t:'steam',from:[[60,14],[76,14]],col:'#f08a52'},{t:'needle',from:[98,54],dir:1},{t:'needle',from:[98,62],dir:1},{t:'ping',from:[[60,10],[86,14]],icons:['coin','err'],every:2}],
    defeat:[{t:'steam',from:[[60,30]]},{t:'ping',from:[[60,20],[80,24]],icons:['coin'],every:4}] },
  sicsoc:{
    idle:[{t:'flick',box:[60,6,28,16],cols:['#ff7ae0','#6fe3d3','#a6f07a'],n:8},{t:'ping',from:[[96,12],[42,46],[108,24],[30,58]],icons:['note','note','heart','note'],every:3}],
    hurt:[{t:'flick',box:[60,6,28,30],cols:['#ff7ae0','#6fe3d3','#ffffff'],n:30}],
    taunt:[{t:'flick',box:[60,6,28,16],cols:['#ff7ae0','#6fe3d3','#a6f07a'],n:14},{t:'ping',from:[[96,12],[42,46],[108,24],[70,0]],icons:['note','heart','note','note'],every:2}],
    rage:[{t:'flick',box:[56,4,34,34],cols:['#ff6a3d','#ff7ae0','#ffef6b'],n:20},{t:'steam',from:[[70,4]],col:'#f08a52'},{t:'ping',from:[[96,12],[42,46]],icons:['note','err'],every:2}],
    defeat:[{t:'ping',from:[[70,10]],icons:['note'],every:5}] },
  sinstaram:{
    idle:[{t:'flash',at:[52,30],every:20},{t:'ping',from:[[24,12],[80,12],[90,40],[10,40]],icons:['heart','thumb','heart','bell'],every:3}],
    hurt:[{t:'flash',at:[52,30],every:4},{t:'scan',box:[40,18,24,24],noise:20}],
    taunt:[{t:'flash',at:[52,30],every:8},{t:'ping',from:[[24,12],[80,12],[90,40],[52,0]],icons:['heart','thumb','heart'],every:2}],
    rage:[{t:'flash',at:[52,30],every:6},{t:'steam',from:[[30,6],[74,6]],col:'#f08a52'},{t:'ping',from:[[24,12],[80,12]],icons:['err','heart'],every:2}],
    defeat:[{t:'steam',from:[[50,30]]}] }
});
["dyefone", "sandroid", "hexbox", "pintendo", "sicsoc", "sinstaram"].forEach(function(k){ PXB_POSE[k]={idle:'idle',attack:'idle',hurt:'idle',block:'idle',taunt:'idle',rage:'rage',defeat:'idle'}; });
/* the plate shows the boss's name (without a leading 'The'), shrunk until it fits */
function abcPxBossName(){
  const card=document.querySelector('.char.opp.boss'), n=card&&card.querySelector('.pc-name'); if(!n) return;
  let nm='', full=''; try{ full=S.opp.team[S.opp.activeIdx].name; nm=full.replace(/^(the|a|an)\s+/i,''); }catch(e){} if(!nm) return;   /* 'The Sensory Over-lord' -> 'Sensory Over-lord' */
  if(n.textContent!==nm){ n.textContent=nm; n.title=full; }
  n.style.setProperty('white-space','nowrap','important'); n.style.setProperty('overflow','hidden','important'); n.style.setProperty('text-overflow','clip','important');
  n.style.removeProperty('font-size'); n.style.removeProperty('letter-spacing');
  let fs=parseFloat(getComputedStyle(n).fontSize)||12, guard=0;
  while(n.scrollWidth>n.clientWidth+1 && fs>7.5 && guard++<20){ fs-=.5; n.style.setProperty('font-size',fs+'px','important'); if(fs<10) n.style.setProperty('letter-spacing','0','important'); }
  if(n.scrollWidth>n.clientWidth+1){   /* still too long: two lines at a readable size */
    n.style.setProperty('white-space','normal','important'); n.style.setProperty('line-height','1.05','important'); n.style.setProperty('font-size','8px','important'); }
}
'''

for l, a, rep in EDITS:
    if rep is None: rep = a + JS
    s = s.replace(a, rep, 1)
for need in [MARK, 'Object.assign(PXB_ART,', 'abcPxBossName();', "if(PXB_ART[k]) return k;", '(RIGS[boss]||{}).idle', '_ia.w/_ia.h']:
    if need not in s:
        sys.exit(f'{TAG} ERROR: post-check failed ({need}). Nothing written.')
bak = SRC + '.bak_' + datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
shutil.copyfile(SRC, bak)
open(SRC, 'w', encoding='utf-8').write(s)
print(f'{TAG} Applied.  Backup:', bak)
print(f'{TAG} Next: python3 build.py')
